238	/* Returns NULL if successful, otherwise a malloc()'d string describing the
239	 * error.  The caller is responsible for freeing the returned string. */
240	static char * OVS_WARN_UNUSED_RESULT
241	learn_parse_spec(const char *orig, char *name, char *value,
242	                 const struct ofputil_port_map *port_map,
243	                 struct ofpact_learn_spec *spec,
244	                 struct ofpbuf *ofpacts, struct match *match)
245	{
246	    /* Parse destination and check prerequisites. */
247	    struct mf_subfield dst;
248	
249	    char *error = mf_parse_subfield(&dst, name);
250	    bool parse_error = error != NULL;
251	    free(error);
252	
253	    if (!parse_error) {
254	        if (!mf_nxm_header(dst.field->id)) {
255	            return xasprintf("%s: experimenter OXM field '%s' not supported",
256	                             orig, name);
257	        }
258	        spec->dst = dst;
259	        spec->n_bits = dst.n_bits;
260	        spec->dst_type = NX_LEARN_DST_MATCH;
261	
262	        /* Parse source and check prerequisites. */
263	        if (value[0] != '\0') {
264	            struct mf_subfield src;
265	            error = mf_parse_subfield(&src, value);
266	            if (error) {
267	                union mf_value imm;
268	                char *imm_error = NULL;
269	
270	                /* Try an immediate value. */
271	                if (dst.ofs == 0 && dst.n_bits == dst.field->n_bits) {
272	                    /* Full field value. */
273	                    imm_error = mf_parse_value(dst.field, value, port_map,
274	                                               &imm);
275	                } else {
276	                    char *tail;
277	                    /* Partial field value. */
278	                    if (parse_int_string(value, (uint8_t *)&imm,
279	                                          dst.field->n_bytes, &tail)
280	                        || *tail != 0) {
281	                        imm_error = xasprintf("%s: cannot parse integer value", orig);
282	                    }
283	
284	                    if (!imm_error &&
285	                        !bitwise_is_all_zeros(&imm, dst.field->n_bytes,
286	                                              dst.n_bits,
287	                                              dst.field->n_bytes * 8 - dst.n_bits)) {
288	                        struct ds ds;
289	
290	                        ds_init(&ds);
291	                        mf_format(dst.field, &imm, NULL, NULL, &ds);
292	                        imm_error = xasprintf("%s: value %s does not fit into %d bits",
293	                                              orig, ds_cstr(&ds), dst.n_bits);
294	                        ds_destroy(&ds);
295	                    }
296	                }
297	                if (imm_error) {
298	                    char *err = xasprintf("%s: %s value %s cannot be parsed as a subfield (%s) or an immediate value (%s)",
299	                                          orig, name, value, error, imm_error);
300	                    free(error);
301	                    free(imm_error);
302	                    return err;
303	                }
304	
305	                spec->src_type = NX_LEARN_SRC_IMMEDIATE;
306	
307	                /* Update 'match' to allow for satisfying destination
308	                 * prerequisites. */
309	                mf_write_subfield_value(&dst, &imm, match);
310	
311	                /* Push value last, as this may reallocate 'spec'! */
312	                unsigned int imm_bytes = DIV_ROUND_UP(dst.n_bits, 8);
313	                uint8_t *src_imm = ofpbuf_put_zeros(ofpacts,
314	                                                    OFPACT_ALIGN(imm_bytes));
315	                memcpy(src_imm, &imm, imm_bytes);
316	
317	                free(error);
318	                return NULL;
319	            }
320	            spec->src = src;
321	            if (spec->src.n_bits != spec->dst.n_bits) {
322	                return xasprintf("%s: bit widths of %s (%u) and %s (%u) "
323	                                 "differ", orig, name, spec->src.n_bits, value,
324	                                 spec->dst.n_bits);
325	            }
326	        } else {
327	            spec->src = spec->dst;
328	        }
329	
330	        spec->src_type = NX_LEARN_SRC_FIELD;
331	    } else if (!strcmp(name, "load")) {
332	        union mf_subvalue imm;
333	        char *tail;
334	        char *dst_value = strstr(value, "->");
335	
336	        if (dst_value == value) {
337	            return xasprintf("%s: missing source before `->' in `%s'", name,
338	                             value);
339	        }
340	        if (!dst_value) {
341	            return xasprintf("%s: missing `->' in `%s'", name, value);
342	        }
343	
344	        if (!parse_int_string(value, imm.u8, sizeof imm.u8, (char **) &tail)
345	            && tail != value) {
346	            if (tail != dst_value) {
347	                return xasprintf("%s: garbage before `->' in `%s'",
348	                                 name, value);
349	            }
350	
351	            error = learn_parse_load_immediate(&imm, dst_value + 2, value, spec,
352	                                               ofpacts);
353	            if (error) {
354	                return error;
355	            }
356	        } else {
357	            struct ofpact_reg_move move;
358	
359	            error = nxm_parse_reg_move(&move, value);
360	            if (error) {
361	                return error;
362	            }
363	
364	            spec->n_bits = move.src.n_bits;
365	            spec->src_type = NX_LEARN_SRC_FIELD;
366	            spec->src = move.src;
367	            spec->dst_type = NX_LEARN_DST_LOAD;
368	            spec->dst = move.dst;
369	        }
370	    } else if (!strcmp(name, "output")) {
371	        error = mf_parse_subfield(&spec->src, value);
372	        if (error) {
373	            return error;
374	        }
375	
376	        spec->n_bits = spec->src.n_bits;
377	        spec->src_type = NX_LEARN_SRC_FIELD;
378	        spec->dst_type = NX_LEARN_DST_OUTPUT;
379	    } else {
380	        return xasprintf("%s: unknown keyword %s", orig, name);
381	    }
382	
383	    return NULL;
384	}
385	
386	/* Returns NULL if successful, otherwise a malloc()'d string describing the
387	 * error.  The caller is responsible for freeing the returned string. */
388	static char * OVS_WARN_UNUSED_RESULT
389	learn_parse__(char *orig, char *arg, const struct ofputil_port_map *port_map,
390	              const struct ofputil_table_map *table_map,
391	              struct ofpbuf *ofpacts)
392	{
393	    struct ofpact_learn *learn;
394	    struct match match;
395	    char *name, *value;
396	
397	    learn = ofpact_put_LEARN(ofpacts);
398	    learn->idle_timeout = OFP_FLOW_PERMANENT;
399	    learn->hard_timeout = OFP_FLOW_PERMANENT;
400	    learn->priority = OFP_DEFAULT_PRIORITY;
401	    learn->table_id = 1;
402	
403	    match_init_catchall(&match);
404	    while (ofputil_parse_key_value(&arg, &name, &value)) {
405	        if (!strcmp(name, "table")) {
406	            if (!ofputil_table_from_string(value, table_map,
407	                                           &learn->table_id)) {
408	                return xasprintf("unknown table \"%s\"", value);
409	            } else if (learn->table_id == 255) {
410	                return xasprintf("%s: table id 255 not valid for `learn' "
411	                                 "action", orig);
412	            }
413	        } else if (!strcmp(name, "priority")) {
414	            learn->priority = atoi(value);
415	        } else if (!strcmp(name, "idle_timeout")) {
416	            learn->idle_timeout = atoi(value);
417	        } else if (!strcmp(name, "hard_timeout")) {
418	            learn->hard_timeout = atoi(value);
419	        } else if (!strcmp(name, "fin_idle_timeout")) {
420	            learn->fin_idle_timeout = atoi(value);
421	        } else if (!strcmp(name, "fin_hard_timeout")) {
422	            learn->fin_hard_timeout = atoi(value);
423	        } else if (!strcmp(name, "cookie")) {
424	            learn->cookie = htonll(strtoull(value, NULL, 0));
425	        } else if (!strcmp(name, "send_flow_rem")) {
426	            learn->flags |= NX_LEARN_F_SEND_FLOW_REM;
427	        } else if (!strcmp(name, "delete_learned")) {
428	            learn->flags |= NX_LEARN_F_DELETE_LEARNED;
429	        } else if (!strcmp(name, "limit")) {
430	            learn->limit = atoi(value);
431	        } else if (!strcmp(name, "result_dst")) {
432	            char *error;
433	            learn->flags |= NX_LEARN_F_WRITE_RESULT;
434	            error = mf_parse_subfield(&learn->result_dst, value);
435	            if (error) {
436	                return error;
437	            }
438	            if (!learn->result_dst.field->writable) {
439	                return xasprintf("%s is read-only", value);
440	            }
441	            if (learn->result_dst.n_bits != 1) {
442	                return xasprintf("result_dst in 'learn' action must be a "
443	                                 "single bit");
444	            }
445	        } else {
446	            struct ofpact_learn_spec *spec;
447	            char *error;
448	
449	            spec = ofpbuf_put_zeros(ofpacts, sizeof *spec);
450	            error = learn_parse_spec(orig, name, value, port_map,
451	                                     spec, ofpacts, &match);
452	            if (error) {
453	                return error;
454	            }
455	            learn = ofpacts->header;
456	        }
457	    }
458	    ofpact_finish_LEARN(ofpacts, &learn);
459	
460	    return NULL;
461	}
462	
463	/* Parses 'arg' as a set of arguments to the "learn" action and appends a
464	 * matching OFPACT_LEARN action to 'ofpacts'.  ovs-ofctl(8) describes the
465	 * format parsed.
466	 *
467	 * Returns NULL if successful, otherwise a malloc()'d string describing the
468	 * error.  The caller is responsible for freeing the returned string.
469	 *
470	 * If 'flow' is nonnull, then it should be the flow from a struct match that is
471	 * the matching rule for the learning action.  This helps to better validate
472	 * the action's arguments.
473	 *
474	 * Modifies 'arg'. */
475	char * OVS_WARN_UNUSED_RESULT
476	learn_parse(char *arg, const struct ofputil_port_map *port_map,
477	            const struct ofputil_table_map *table_map,
478	            struct ofpbuf *ofpacts)
479	{
480	    char *orig = xstrdup(arg);
481	    char *error = learn_parse__(orig, arg, port_map, table_map, ofpacts);
482	    free(orig);
483	    return error;
484	}
485	
486	/* Appends a description of 'learn' to 's', in the format that ovs-ofctl(8)
487	 * describes. */
488	void
489	learn_format(const struct ofpact_learn *learn,
490	             const struct ofputil_port_map *port_map,
491	             const struct ofputil_table_map *table_map,
492	             struct ds *s)
493	{
494	    const struct ofpact_learn_spec *spec;
495	    struct match match;
496	
497	    match_init_catchall(&match);
498	
499	    ds_put_format(s, "%slearn(%s%stable=%s",
500	                  colors.learn, colors.end, colors.special, colors.end);
501	    ofputil_format_table(learn->table_id, table_map, s);
502	    if (learn->idle_timeout != OFP_FLOW_PERMANENT) {
503	        ds_put_format(s, ",%sidle_timeout=%s%"PRIu16,
504	                      colors.param, colors.end, learn->idle_timeout);
505	    }
506	    if (learn->hard_timeout != OFP_FLOW_PERMANENT) {
507	        ds_put_format(s, ",%shard_timeout=%s%"PRIu16,
508	                      colors.param, colors.end, learn->hard_timeout);
509	    }
510	    if (learn->fin_idle_timeout) {
511	        ds_put_format(s, ",%sfin_idle_timeout=%s%"PRIu16,
512	                      colors.param, colors.end, learn->fin_idle_timeout);
513	    }
514	    if (learn->fin_hard_timeout) {
515	        ds_put_format(s, "%s,fin_hard_timeout=%s%"PRIu16,
516	                      colors.param, colors.end, learn->fin_hard_timeout);
517	    }
518	    if (learn->priority != OFP_DEFAULT_PRIORITY) {
519	        ds_put_format(s, "%s,priority=%s%"PRIu16,
520	                      colors.special, colors.end, learn->priority);
521	    }
522	    if (learn->flags & NX_LEARN_F_SEND_FLOW_REM) {
523	        ds_put_format(s, ",%ssend_flow_rem%s", colors.value, colors.end);
524	    }
525	    if (learn->flags & NX_LEARN_F_DELETE_LEARNED) {
526	        ds_put_format(s, ",%sdelete_learned%s", colors.value, colors.end);
527	    }
528	    if (learn->cookie != 0) {
529	        ds_put_format(s, ",%scookie=%s%#"PRIx64,
530	                      colors.param, colors.end, ntohll(learn->cookie));
531	    }
532	    if (learn->limit != 0) {
533	        ds_put_format(s, ",%slimit=%s%"PRIu32,
534	                      colors.param, colors.end, learn->limit);
535	    }
536	    if (learn->flags & NX_LEARN_F_WRITE_RESULT) {
537	        ds_put_format(s, ",%sresult_dst=%s", colors.param, colors.end);
538	        mf_format_subfield(&learn->result_dst, s);
539	    }
540	
541	    OFPACT_LEARN_SPEC_FOR_EACH (spec, learn) {
542	        unsigned int n_bytes = DIV_ROUND_UP(spec->n_bits, 8);
543	        ds_put_char(s, ',');
544	
545	        switch (spec->src_type | spec->dst_type) {
546	        case NX_LEARN_SRC_IMMEDIATE | NX_LEARN_DST_MATCH: {
547	            if (spec->dst.ofs == 0
548	                && spec->dst.n_bits == spec->dst.field->n_bits) {
549	                union mf_value value;
550	
551	                memset(&value, 0, sizeof value);
552	                memcpy(&value.b[spec->dst.field->n_bytes - n_bytes],
553	                       ofpact_learn_spec_imm(spec), n_bytes);
554	                ds_put_format(s, "%s%s=%s", colors.param,
555	                              spec->dst.field->name, colors.end);
556	                mf_format(spec->dst.field, &value, NULL, port_map, s);
557	            } else {
558	                ds_put_format(s, "%s", colors.param);
559	                mf_format_subfield(&spec->dst, s);
560	                ds_put_format(s, "=%s", colors.end);
561	                ds_put_hex(s, ofpact_learn_spec_imm(spec), n_bytes);
562	            }
563	            break;
564	        }
565	        case NX_LEARN_SRC_FIELD | NX_LEARN_DST_MATCH:
566	            ds_put_format(s, "%s", colors.param);
567	            mf_format_subfield(&spec->dst, s);
568	            ds_put_format(s, "%s", colors.end);
569	            if (spec->src.field != spec->dst.field ||
570	                spec->src.ofs != spec->dst.ofs) {
571	                ds_put_format(s, "%s=%s", colors.param, colors.end);
572	                mf_format_subfield(&spec->src, s);
573	            }
574	            break;
575	
576	        case NX_LEARN_SRC_IMMEDIATE | NX_LEARN_DST_LOAD:
577	            ds_put_format(s, "%sload:%s", colors.special, colors.end);
578	            ds_put_hex(s, ofpact_learn_spec_imm(spec), n_bytes);
579	            ds_put_format(s, "%s->%s", colors.special, colors.end);
580	            mf_format_subfield(&spec->dst, s);
581	            break;
582	
583	        case NX_LEARN_SRC_FIELD | NX_LEARN_DST_LOAD:
584	            ds_put_format(s, "%sload:%s", colors.special, colors.end);
585	            mf_format_subfield(&spec->src, s);
586	            ds_put_format(s, "%s->%s", colors.special, colors.end);
587	            mf_format_subfield(&spec->dst, s);
588	            break;
589	
590	        case NX_LEARN_SRC_FIELD | NX_LEARN_DST_OUTPUT:
591	            ds_put_format(s, "%soutput:%s", colors.special, colors.end);
592	            mf_format_subfield(&spec->src, s);
593	            break;
594	        }
595	    }
596	    ds_put_format(s, "%s)%s", colors.learn, colors.end);
597	}
